"use client"
import * as React from "react"
import { AnimatePresence, Reorder, motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion"
import { Check, ImagePlus, Loader2, Star, X } from "lucide-react"
import { cn } from "@/lib/utils"

export interface ReviewPayload {
  /** 0.5 to 5 in steps of 0.5 */
  rating: number
  photos: File[]
  highlights: string[]
  text: string
}

export interface PhotoReviewFormProps {
  title?: string
  subtitle?: string
  /** Chips under "What stood out". */
  highlights?: string[]
  maxPhotos?: number
  /** Max size per photo in MB. Default 5. */
  maxPhotoMb?: number
  maxLength?: number
  onSubmit?: (review: ReviewPayload) => Promise<void>
  className?: string
}

const WORDS: Record<number, string> = {
  0.5: "Really not good", 1: "Disappointing", 1.5: "Below what I hoped", 2: "Just okay, if I'm honest", 2.5: "Mixed feelings",
  3: "Decent", 3.5: "Pretty good", 4: "Really good", 4.5: "Nearly perfect", 5: "Loved it",
}
const snap = (n: number) => Math.min(5, Math.max(0, Math.round(n * 2) / 2))

const GRADIENT = "linear-gradient(120deg,#5a49f0,#7c5cff 55%,#ff6b6b)"
const SPARK = ["#ffd166", "#ff9f6b", "#ff6b6b", "#22d3ee", "#ffffff"]
const ACCENT_TEXT = "text-primary dark:text-[color-mix(in_oklab,var(--primary),white_45%)]"

function Stars({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  const reduce = useReducedMotion()
  const uid = React.useId().replace(/:/g, "")
  const [hover, setHover] = React.useState<number | null>(null)
  const [wave, setWave] = React.useState<{ n: number; from: number; to: number }>({ n: 0, from: 0, to: 0 })
  const shown = hover ?? value
  const ref = React.useRef<HTMLDivElement>(null)
  const fromX = (x: number) => { const b = ref.current!.getBoundingClientRect(); return Math.min(5, Math.max(0.5, Math.ceil(((x - b.left) / b.width) * 10) / 2)) }
  const set = (v: number) => { setWave((w) => ({ n: w.n + 1, from: Math.min(value, v), to: v })); onChange(v) }
  const onKey = (e: React.KeyboardEvent) => {
    const k = e.key
    if (k === "ArrowRight" || k === "ArrowUp") set(snap(value + 0.5))
    else if (k === "ArrowLeft" || k === "ArrowDown") set(snap(value - 0.5))
    else if (k === "Home") set(0)
    else if (k === "End") set(5)
    else if (/^[1-5]$/.test(k)) set(Number(k))
    else return
    e.preventDefault()
  }
  return (
    <div>
      <svg width="0" height="0" className="absolute" aria-hidden><defs>
        <linearGradient id={`g${uid}`} x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#ffd166" /><stop offset="0.55" stopColor="#ff9f6b" /><stop offset="1" stopColor="#ff6b6b" /></linearGradient>
      </defs></svg>
      <div ref={ref} role="slider" tabIndex={0} aria-label="Rating" aria-valuemin={0} aria-valuemax={5} aria-valuenow={value} aria-valuetext={value ? `${value} out of 5 stars` : "No rating yet"}
        onKeyDown={onKey} onPointerMove={(e) => e.pointerType === "mouse" && setHover(fromX(e.clientX))} onPointerLeave={() => setHover(null)} onClick={(e) => set(fromX(e.clientX))}
        className="relative inline-flex cursor-pointer touch-none rounded-xl outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring">
        {[0, 1, 2, 3, 4].map((i) => {
          const fill = Math.min(1, Math.max(0, shown - i))
          const lit = value > i
          const d = Math.abs(i - wave.from) // distance in stars from where the wave starts
          return (
            <motion.span key={`${i}-${wave.n}`} className="relative grid size-12 place-items-center"
              animate={!reduce && wave.n && i < Math.ceil(wave.to) && i >= Math.floor(wave.from) ? { scale: [1, 1.5, 0.92, 1], rotate: [0, -14, 8, 0], y: [0, -8, 0, 0] } : { scale: 1 }}
              transition={{ duration: 0.55, delay: reduce ? 0 : d * 0.07, ease: "easeOut" }}>
              <Star className="size-9 text-border" strokeWidth={1.5} aria-hidden />
              <span className="absolute inset-0 grid place-items-center" style={{ clipPath: `inset(0 ${(1 - fill) * 100}% 0 0)`, transition: reduce ? undefined : "clip-path 140ms ease-out" }}>
                <Star className="size-9 drop-shadow-[0_0_10px_rgba(255,140,100,0.65)]" fill={`url(#g${uid})`} stroke={`url(#g${uid})`} strokeWidth={1.5} aria-hidden />
              </span>
              {!reduce && wave.n > 0 && lit && i >= Math.floor(wave.from) && (
                <span key={wave.n} aria-hidden className="pointer-events-none absolute inset-0">
                  {Array.from({ length: 7 }).map((_, j) => {
                    const a = (j / 7) * Math.PI * 2 + i, r = 26 + ((j * 13) % 14)
                    return <motion.span key={j} className="absolute left-1/2 top-1/2 -ml-0.5 -mt-0.5 size-1 rounded-full" style={{ background: SPARK[(i + j) % SPARK.length], boxShadow: `0 0 8px ${SPARK[(i + j) % SPARK.length]}` }}
                      initial={{ x: 0, y: 0, opacity: 0, scale: 1 }} animate={{ x: Math.cos(a) * r, y: Math.sin(a) * r, opacity: [0, 1, 0], scale: [1, 1.6, 0] }} transition={{ duration: 0.7, delay: d * 0.07 + 0.08 }} />
                  })}
                </span>
              )}
            </motion.span>
          )
        })}
      </div>
      <div className="mt-1 h-5 text-sm text-muted-foreground" aria-live="polite">
        <AnimatePresence mode="wait" initial={false}>
          <motion.span key={shown} initial={{ opacity: 0, y: reduce ? 0 : 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.12 }} className="inline-block">
            {shown ? <><span className="font-semibold tabular-nums text-foreground">{shown.toFixed(1)}</span> · {WORDS[shown]}</> : "Tap a star, or use the arrow keys. Half stars are fine."}
          </motion.span>
        </AnimatePresence>
      </div>
    </div>
  )
}

interface Photo { id: string; file: File; url: string; tilt: number }

export function PhotoReviewForm({
  title = "How was it?", subtitle = "Your review helps the next person decide.",
  highlights = ["Friendly staff", "Worth the price", "Easy to find", "Clean", "Quick", "Good for groups"],
  maxPhotos = 3, maxPhotoMb = 5, maxLength = 600, onSubmit, className,
}: PhotoReviewFormProps) {
  const reduce = useReducedMotion()
  const uid = React.useId()
  const [rating, setRating] = React.useState(0)
  const [photos, setPhotos] = React.useState<Photo[]>([])
  const [chips, setChips] = React.useState<string[]>([])
  const [text, setText] = React.useState("")
  const [over, setOver] = React.useState(false)
  const [note, setNote] = React.useState("")
  const [state, setState] = React.useState<"idle" | "sending" | "sent" | "error">("idle")
  const input = React.useRef<HTMLInputElement>(null)
  const photosRef = React.useRef(photos)
  photosRef.current = photos
  React.useEffect(() => () => photosRef.current.forEach((p) => URL.revokeObjectURL(p.url)), [])

  const mx = useMotionValue(0.5), my = useMotionValue(0.5)
  const rx = useSpring(useTransform(my, [0, 1], [3, -3]), { stiffness: 120, damping: 18 }), ry = useSpring(useTransform(mx, [0, 1], [-4, 4]), { stiffness: 120, damping: 18 })
  const px = useMotionValue(-300), py = useMotionValue(-300)
  const glow = useMotionTemplate`radial-gradient(260px circle at ${px}px ${py}px, color-mix(in oklab, var(--primary) 16%, transparent), transparent 70%)`

  const addFiles = (list: FileList | File[] | null) => {
    if (!list) return
    const room = maxPhotos - photos.length
    const files = Array.from(list)
    const good = files.filter((f) => f.type.startsWith("image/") && f.size <= maxPhotoMb * 1024 * 1024)
    const skipped = files.length - good.length
    const take = good.slice(0, Math.max(0, room))
    setNote(room <= 0 ? `That's the limit: ${maxPhotos} photos.` : skipped ? `${skipped} skipped. Photos only, up to ${maxPhotoMb} MB each.` : good.length > take.length ? `Kept the first ${take.length}. The limit is ${maxPhotos} photos.` : "")
    setPhotos((p) => [...p, ...take.map((file, i) => ({ id: `${file.name}-${file.size}-${Math.random().toString(36).slice(2, 7)}`, file, url: URL.createObjectURL(file), tilt: ((p.length + i) % 2 ? 1 : -1) * (2 + Math.random() * 4) }))])
  }
  const remove = (id: string) => setPhotos((p) => { p.filter((x) => x.id === id).forEach((x) => URL.revokeObjectURL(x.url)); return p.filter((x) => x.id !== id) })
  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!rating || state === "sending") return
    setState("sending")
    try { await onSubmit?.({ rating, photos: photos.map((p) => p.file), highlights: chips, text: text.trim() }); setState("sent") } catch { setState("error") }
  }
  const left = maxLength - text.length
  const spring = reduce ? { duration: 0.01 } : { type: "spring" as const, stiffness: 420, damping: 30 }

  return (
    <div className={cn("relative w-full max-w-md", className)} style={{ perspective: 1100 }}>
      <motion.div aria-hidden className="pointer-events-none absolute -inset-3 rounded-[2rem] bg-[conic-gradient(from_20deg,#ff6b6b,#6c5cff,#22d3ee,#ff6b6b)] blur-2xl"
        animate={reduce ? { opacity: 0.25 } : { opacity: [0.2, 0.45, 0.2] }} transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }} />
      <motion.form onSubmit={submit} aria-label={title}
        onPointerMove={(e) => { const b = e.currentTarget.getBoundingClientRect(); mx.set((e.clientX - b.left) / b.width); my.set((e.clientY - b.top) / b.height); px.set(e.clientX - b.left); py.set(e.clientY - b.top) }}
        onPointerLeave={() => { mx.set(0.5); my.set(0.5) }}
        style={{ rotateX: reduce ? 0 : rx, rotateY: reduce ? 0 : ry, transformStyle: "preserve-3d" }}
        initial={{ opacity: 0, y: reduce ? 0 : 24 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 140, damping: 18 }}
        className="relative rounded-2xl border border-border bg-card p-5 text-foreground shadow-[0_40px_70px_-35px_rgba(50,35,150,0.5)]">
        {!reduce && <motion.div aria-hidden className="pointer-events-none absolute inset-0 rounded-2xl" style={{ background: glow }} />}
        <header className="relative mb-4" style={{ transform: "translateZ(20px)" }}>
          <h2 className="text-lg font-semibold leading-tight">{title}</h2>
          <p className="mt-1 text-sm text-muted-foreground">{subtitle}</p>
        </header>
        <div className="relative" style={{ transform: "translateZ(30px)" }}><Stars value={rating} onChange={setRating} /></div>

        <fieldset className="relative mt-5" style={{ transform: "translateZ(14px)" }}>
          <legend className="mb-2 text-sm font-medium">What stood out <span className="font-normal text-muted-foreground">(optional)</span></legend>
          <div className="flex flex-wrap gap-2">
            {highlights.map((h) => {
              const on = chips.includes(h)
              return (
                <motion.button key={h} layout type="button" aria-pressed={on} onClick={() => setChips((c) => (on ? c.filter((x) => x !== h) : [...c, h]))}
                  animate={{ scale: 1 }} whileTap={reduce ? undefined : { scale: 0.86, rotate: -2 }} whileHover={reduce ? undefined : { y: -2 }}
                  transition={{ type: "spring", stiffness: 500, damping: 14 }} style={on ? { background: GRADIENT } : undefined}
                  className={cn("relative inline-flex min-h-11 items-center gap-1.5 rounded-full border px-3.5 text-sm outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
                    on ? "border-transparent font-medium text-white shadow-[0_6px_18px_-6px_rgba(108,92,255,0.8)]" : "border-border bg-background hover:border-primary/60")}>
                  <AnimatePresence initial={false}>
                    {on && <motion.span key="c" initial={{ width: 0, opacity: 0, rotate: -90 }} animate={{ width: 14, opacity: 1, rotate: 0 }} exit={{ width: 0, opacity: 0 }} transition={{ type: "spring", stiffness: 400, damping: 16 }} className="overflow-hidden"><Check className="size-3.5" aria-hidden /></motion.span>}
                  </AnimatePresence>
                  {h}
                </motion.button>
              )
            })}
          </div>
        </fieldset>

        <div className="relative mt-5">
          <label htmlFor={`${uid}-t`} className="mb-1.5 block text-sm font-medium">Tell us more <span className="font-normal text-muted-foreground">(optional)</span></label>
          <textarea id={`${uid}-t`} rows={3} value={text} onChange={(e) => setText(e.target.value.slice(0, maxLength))} placeholder="What would you tell a friend about it?" aria-describedby={`${uid}-c`}
            className="block w-full resize-none rounded-xl border border-border bg-background px-3 py-2.5 text-sm outline-none transition-shadow placeholder:text-muted-foreground focus:border-primary focus:shadow-[0_0_0_4px_color-mix(in_oklab,var(--primary)_20%,transparent)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring" />
          <div id={`${uid}-c`} className="mt-2 flex items-center gap-3">
            <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted"><motion.div className="h-full rounded-full" style={{ background: left < 60 ? "#ff6b6b" : GRADIENT }} animate={{ width: `${(text.length / maxLength) * 100}%` }} transition={{ type: "spring", stiffness: 160, damping: 14 }} /></div>
            <span className={cn("text-xs tabular-nums", left < 60 ? "text-red-700 dark:text-red-300" : "text-muted-foreground")}>{text.length} / {maxLength}</span>
          </div>
        </div>

        <div className="relative mt-5" style={{ transform: "translateZ(10px)" }}>
          <p className="mb-2 text-sm font-medium">Photos <span className="font-normal text-muted-foreground">({photos.length} of {maxPhotos})</span></p>
          {/* the "desk" the photos land on */}
          <div onDragOver={(e) => { e.preventDefault(); setOver(true) }} onDragLeave={() => setOver(false)} onDrop={(e) => { e.preventDefault(); setOver(false); addFiles(e.dataTransfer.files) }}
            className="rounded-2xl border border-border bg-[linear-gradient(180deg,var(--muted),color-mix(in_oklab,var(--muted)_60%,var(--card)))] p-3 shadow-[inset_0_2px_12px_rgba(0,0,0,0.12)]">
            <Reorder.Group axis="x" values={photos} onReorder={setPhotos} className="flex min-h-28 flex-wrap items-center gap-3">
              <AnimatePresence initial={false}>
                {photos.map((p, i) => (
                  <Reorder.Item key={p.id} value={p} layout="position"
                    initial={{ opacity: 0, y: reduce ? 0 : -220, rotate: reduce ? 0 : p.tilt * -6, scale: reduce ? 1 : 1.5 }}
                    animate={{ opacity: 1, y: 0, rotate: p.tilt, scale: 1, boxShadow: "0 6px 14px rgba(0,0,0,0.28)" }}
                    exit={{ opacity: 0, y: reduce ? 0 : 60, rotate: p.tilt * 4, scale: 0.6, transition: { duration: 0.25 } }}
                    transition={reduce ? { duration: 0.01 } : { type: "spring", stiffness: 170, damping: 11, mass: 1.1, delay: i * 0.06 }}
                    whileDrag={reduce ? undefined : { scale: 1.12, rotate: 0, zIndex: 30, boxShadow: "0 22px 36px rgba(0,0,0,0.4)" }}
                    className="relative h-[6.2rem] w-[5.2rem] cursor-grab list-none rounded-md bg-white p-1.5 pb-5 active:cursor-grabbing">
                    <img src={p.url} alt={`Your photo ${i + 1}`} draggable={false} className="size-full select-none rounded-sm object-cover" />
                    <button type="button" onClick={() => remove(p.id)} aria-label={`Remove photo ${i + 1}`} className="absolute -right-3 -top-3 grid size-11 place-items-center rounded-full outline-none focus-visible:outline-2 focus-visible:outline-ring">
                      <span className="grid size-6 place-items-center rounded-full bg-foreground text-background shadow"><X className="size-3.5" aria-hidden /></span>
                    </button>
                  </Reorder.Item>
                ))}
              </AnimatePresence>
              {photos.length < maxPhotos && (
                <motion.li layout="position" className="list-none">
                  <motion.button type="button" onClick={() => input.current?.click()} animate={{ scale: over && !reduce ? 1.1 : 1 }} whileHover={reduce ? undefined : { scale: 1.05 }} whileTap={reduce ? undefined : { scale: 0.93 }}
                    aria-label={`Add photos, ${maxPhotos - photos.length} left`}
                    className={cn("grid h-[6.2rem] w-[5.2rem] place-items-center rounded-md border-2 border-dashed text-muted-foreground outline-none transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", over ? "border-primary bg-primary/10" : "border-border hover:border-primary/60 hover:text-foreground")}>
                    <span className="flex flex-col items-center gap-1 text-xs"><ImagePlus className="size-5" aria-hidden />Add photo</span>
                  </motion.button>
                </motion.li>
              )}
            </Reorder.Group>
            <input ref={input} type="file" accept="image/*" multiple hidden onChange={(e) => { addFiles(e.target.files); e.target.value = "" }} />
          </div>
          <p aria-live="polite" className="mt-2 min-h-4 text-xs text-muted-foreground">{note || (photos.length > 1 ? "Drag to change the order. Photos stay on this device until you send." : "Drop photos here or tap to pick. They stay on this device until you send.")}</p>
        </div>

        <motion.button type="submit" disabled={!rating || state === "sending"} whileTap={reduce || !rating ? undefined : { scale: 0.96 }} whileHover={reduce || !rating ? undefined : { y: -2 }}
          style={{ background: GRADIENT }}
          className="relative mt-4 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl px-4 text-sm font-semibold text-white shadow-[0_12px_30px_-10px_rgba(108,92,255,0.8)] outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:opacity-45 disabled:shadow-none">
          {state === "sending" && <Loader2 className="size-4 animate-spin motion-reduce:animate-none" aria-hidden />}
          {state === "sent" && <Check className="size-4" aria-hidden />}
          {state === "sent" ? "Thanks for the review" : state === "sending" ? "Posting" : state === "error" ? "Couldn't post. Try again" : rating ? "Post review" : "Choose a rating first"}
        </motion.button>
      </motion.form>
    </div>
  )
}

export default function Demo() {
  return <PhotoReviewForm title="How was your visit to Fernwood Bakery?" onSubmit={() => new Promise((r) => setTimeout(r, 1000))} />
}

